mapper.select:
SELECT * FROM (SELECT b.user_code as usercode,b.user_name as username,plan.plan_startdate,b.name, CASE WHEN b.gender = 1 THEN '男' ELSE '女' END AS sex FROM `yh_user_make_card` AS a INNER JOIN `yh_user_reginfo` AS b ON a.`user_code`=b.user_code LEFT JOIN yh_user_healthy_plan plan ON a.user_code=plan.user_code
a.doctor=(SELECT id FROM `yh_user_admin_info` WHERE user_code=#{usercode}) AND a.user_code != '' AND a.user_code IS NOT NULL AND ((plan_state=1 and plan_day=1) OR plan_startdate is NULL)
AND a.Org_Id=#{orgid}
AND b.name LIKE CONCAT('%',#{nameLike},'%')
ORDER BY plan_startdate
)s GROUP BY s.usercode ORDER BY s.plan_startdate DESC

SELECT * FROM (SELECT b.user_code as usercode,b.user_name as username,plan.plan_startdate,b.name, CASE WHEN b.gender = 1 THEN '男' ELSE '女' END AS sex FROM `yh_user_make_card` AS a INNER JOIN `yh_user_reginfo` AS b ON a.`user_code`=b.user_code LEFT JOIN yh_user_healthy_plan plan ON a.user_code=plan.user_code
a.doctor=(SELECT id FROM `yh_user_admin_info` WHERE user_code=#{usercode}) AND a.user_code != '' AND a.user_code IS NOT NULL AND ((plan_state=1 and plan_day=1) OR plan_startdate is NULL OR (plan_state=0 AND plan_day=1))
AND a.Org_Id=#{orgid}
AND b.name LIKE CONCAT('%',#{nameLike},'%')
ORDER BY plan_startdate
)s GROUP BY s.usercode ORDER BY s.plan_startdate DESC
